43: /**
44:  * A critic to detect when there are component-instances that
45:  * are not inside a node-instance
46:  **/
47: 
48: public class CrCompInstanceWithoutNode extends CrUML {
49: 
50:     public CrCompInstanceWithoutNode() {
51: 	setHeadline("ComponentInstances normally are inside nodes");
52: 	addSupportedDecision(CrUML.decPATTERNS);
53:     }
54: 
55:     public boolean predicate2(Object dm, Designer dsgr) {
56: 	if (!(dm instanceof UMLDeploymentDiagram)) return NO_PROBLEM;
57: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) dm;
58: 	VectorSet offs = computeOffenders(dd); 
59: 	if (offs == null) return NO_PROBLEM; 
60: 	return PROBLEM_FOUND; 
61:     }
62: 
63:     public ToDoItem toDoItem(Object dm, Designer dsgr) { 
64: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) dm;
65: 	VectorSet offs = computeOffenders(dd); 
66: 	return new UMLToDoItem(this, offs, dsgr); 
67:     } 
68:  
69:     public boolean stillValid(ToDoItem i, Designer dsgr) { 
70: 	if (!isActive()) return false; 
71: 	VectorSet offs = i.getOffenders(); 
72: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) offs.firstElement();
73: 	//if (!predicate(dm, dsgr)) return false; 
74: 	VectorSet newOffs = computeOffenders(dd); 
75: 	boolean res = offs.equals(newOffs); 
76: 	return res; 
77:     } 
78: 
79:     /**
80:      * If there are component-instances that have no enclosing FigMNodeInstance
81:      * the returned vector-set is not null. Then in the vector-set
82:      * are the UMLDeploymentDiagram and all FigComponentInstances with no
83:      * enclosing FigMNodeInstance
84:      **/
85:     public VectorSet computeOffenders(UMLDeploymentDiagram dd) { 
86: 
87: 	Vector figs = dd.getLayer().getContents();
88: 	VectorSet offs = null;
89: 	int size = figs.size();
90: 	boolean isNode = false;
91: 	for (int j = 0; j < size; j++) {
92: 	    Object obj = figs.elementAt(j);
93: 	    if (obj instanceof FigMNodeInstance) isNode = true;
94: 	}
95: 	for (int i = 0; i < size; i++) {
96: 	    Object obj = figs.elementAt(i);
97: 	    if (!(obj instanceof FigComponentInstance)) continue;
98: 	    FigComponentInstance fc = (FigComponentInstance) obj;
99: 	    if (fc.getEnclosingFig() == null && isNode == true) {
100: 		if (offs == null) {
101: 		    offs = new VectorSet();
102: 		    offs.addElement(dd);
103: 		}
104: 		offs.addElement(fc);
105: 	    }
106: 	    else if (fc.getEnclosingFig() != null
107: 		     && ((ModelFacade.getNodeInstance(fc.getOwner()))
108: 			 == null))
109: 	    {
110: 		if (offs == null) {
111: 		    offs = new VectorSet();
112: 		    offs.addElement(dd);
113: 		}
114: 		offs.addElement(fc);
115: 	    }
116:      
117: 	}
118: 
119: 	return offs; 
120:     } 
121: 
122: } /* end class CrCompInstanceWithoutNode.java */
