41: /**
42:  * The UMLButtonGroup is the buttongroup behind radio buttons that depict some 
43:  * attribute of a modelelement like visibility.  The radio buttons are controlled
44:  * by the buttongroup. The UMLButtonGroup can be compared to the UMLComboBoxModel
45:  * where the items in the model are the radionbuttons in the buttongroup.
46:  * @since Oct 12, 2002
47:  * @author jaap.branderhorst@xs4all.nl
48:  */
49: public abstract class UMLButtonGroup
50:     extends ButtonGroup
51:     implements UMLUserInterfaceComponent, ActionListener {
52: 
53:     /**
54:      * This map contains the radiobuttons as key and the action that should
55:      * be performed when the button is pressed as value. We don't use 
56:      * the functionallity provided by JDK 1.3 to link an action to a button.
57:      */
58:     private Map _actions = new HashMap();
59:     
60:     private Object _target = null;
61:     
62:     private UMLUserInterfaceContainer _container = null;
63:     
64:     /**
65:      * Constructor for UMLButtonGroup.
66:      */
67:     public UMLButtonGroup(UMLUserInterfaceContainer container) {
68:         super();
69:         setContainer(container);
70:     }
71:     
72:     /**
73:      * Adds a button and an action to the group. When the button is selected,
74:      * the action is fired. If the action is null, no action is done.
75:      * @param button
76:      * @param action
77:      */
78:     public void add(AbstractButton button, Action action) {
79:         _actions.put(button, action);
80:         super.add(button);
81:         button.addActionListener(this);
82:     }
83: 
84:     /**
85:      * When the target changes, the buttonmodel must be updated. Since the 
86:      * API of targetChanged does not have a parameter describing the old and new 
87:      * target, the target is retrieved via the container.
88:      * @see org.argouml.uml.ui.UMLUserInterfaceComponent#targetChanged()
89:      */
90:     public void targetChanged() {
91:         if (getContainer() != null && getContainer().getTarget() != null) {
92:             setTarget(getContainer().getTarget());
93:       
94:         }
95:     }
96: 
97:     /**
98:      * @see org.argouml.uml.ui.UMLUserInterfaceComponent#targetReasserted()
99:      */
100:     public void targetReasserted() {
101:         if (getContainer() != null && getContainer().getTarget() != null) {
102:             setTarget(getContainer().getTarget());
103:       
104:         }
105:     }
106: 
107:     /**
108:      * @see ru.novosoft.uml.MElementListener#propertySet(ru.novosoft.uml.MElementEvent)
109:      */
110:     public void propertySet(MElementEvent e) {
111:         if (e.getSource() == getTarget()) {
112:             buildModel();
113:         }
114:     }
