143:   // accessors
144: 
145:   /** Reply a string that indicates how the text is justified: Left,
146:    *  Center, or Right. */
147:   public String alignmentByName() {
148:     // needs-more-work: index into static array?
149:     // return _AlignmentNames[_alignment];
150:     if (_alignment == JUSTIFY_LEFT) return "Left";
151:     else if (_alignment == JUSTIFY_CENTER) return "Center";
152:     else if (_alignment == JUSTIFY_RIGHT) return "Right";
153:     System.out.println("internal error, unknown text alignment");
154:     return "Unknown";
155:   }
156: 
157:   /** Set the text justification given one of these strings: Left,
158:    *  Center, or Right. */
159:   public void alignmentByName(String alignString) {
160:     if (alignString.equals("Left")) _alignment = JUSTIFY_LEFT;
161:     else if (alignString.equals("Center")) _alignment = JUSTIFY_CENTER;
162:     else if (alignString.equals("Right")) _alignment = JUSTIFY_RIGHT;
163:     _fm = null;
164:   }
