176:   public void setTextFilled(boolean b) { _textFilled = b; }
177:   public boolean getUnderline() { return _underline; }
178:   public void setUnderline(boolean b) { _underline = b; }
179: 
180:   public String getAlignment() { return alignmentByName(); }
181:   public void setAlignment(String align) { alignmentByName(align); }
182:   public int getLineSpacing() { return _lineSpacing; }
183:   public void setLineSpacing(int s) { _lineSpacing = s; calcBounds(); }
184: 
185:   public int getTopMargin() { return _topMargin; }
186:   public void setTopMargin(int m) { _topMargin = m; calcBounds(); }
187:   public int getBotMargin() { return _botMargin; }
188:   public void setBotMargin(int m) { _botMargin = m; calcBounds(); }
189:   public int getLeftMargin() { return _leftMargin; }
190:   public void setLeftMargin(int m) { _leftMargin = m; calcBounds(); }
191:   public int getRightMargin() { return _rightMargin; }
192:   public void setRightMargin(int m) { _rightMargin = m; calcBounds(); }
193: 
194:   public boolean getExpandOnly() { return _expandOnly; }
195:   public void setExpandOnly(boolean b) { _expandOnly = b; }
196: 
197:   public Font getFont() { return _font; }
198:   public void setFont(Font f) { _font = f; _fm = null; calcBounds(); }
199: 
200:   public boolean getItalic() { return _font.isItalic(); }
201:   public void setItalic(boolean b) {
202:     int style = (getBold() ? Font.BOLD : 0) + (b ? Font.ITALIC : 0);
203:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
204:   }
205: 
206:   public boolean getBold() { return _font.isBold(); }
207:   public void setBold(boolean b) {
208:     int style = (b ? Font.BOLD : 0) + (getItalic() ? Font.ITALIC : 0);
209:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
210:   }
211: 
212:   /** Remove the last char from the current string line and return the
213:    *  new string.  Called whenever the user hits the backspace key.
214:    *  Needs-More-Work: Very slow.  This will eventually be replaced by
215:    *  full text editing... if there are any volunteers to do that...*/
216:   public String deleteLastCharFromString(String string) {
217:     int string_length = Math.max(string.length() - 1, 0);
218:     char[] string_char = string.toCharArray();
219:     String new_string = new String(string_char,0,string_length);
220:     return new_string;
221:   }
222: 
223:   /** Delete the last char from the current string. Called whenever
224:    *  the user hits the backspace key */
225:   public void deleteLastChar() {
226:     _curText = deleteLastCharFromString(_curText);
227:     calcBounds();
228:   }
229: 
230:   /** Append a character to the current String .*/
231:   public void append(char c) { setText(_curText + c); }
232: 
233:   /** Append the given String to the current String. */
234:   public void append(String s) { setText(_curText + s); }
235: 
236:   /** set the current String to be the given String. */
237:   public void setText(String s) { _curText = s; calcBounds(); }
238: 
239:   /** Get the String held by this FigText. Multi-line text is
240:    *  represented by newline characters embedded in the String. */
241:   public String getText() { return _curText; }
242: 
243:   ////////////////////////////////////////////////////////////////
244:   // painting methods
245: 
246:   /** Paint the FigText. */
247:   public void paint(Graphics g) {
248:     int chunkX = _x + _leftMargin;
249:     int chunkY = _y + _topMargin;
250:     StringTokenizer lines;
251: 
252:     if (_filled) {
253:       g.setColor(_fillColor);
254:       g.fillRect(_x, _y, _w, _h);
255:     }
256:     if (_lineWidth > 0) {
257:       g.setColor(_lineColor);
258:       g.drawRect(_x - 1, _y - 1, _w + 1, _h + 1);
259:     }
260: 
261:     if (_font != null) g.setFont(_font);
262:     _fm = g.getFontMetrics(_font);
263:     int chunkH = _lineHeight + _lineSpacing;
264:     chunkY = _y + _topMargin + chunkH;
265:     if (_textFilled) {
266:       g.setColor(_textFillColor);
267:       lines = new StringTokenizer(_curText, "\n\r", true);
268:       while (lines.hasMoreTokens()) {
269: 	String curLine = lines.nextToken();
270: 	//if (curLine.equals("\r")) continue;
271: 	int chunkW = _fm.stringWidth(curLine);
272: 	switch (_alignment) {
273: 	case JUSTIFY_LEFT: break;
274: 	case JUSTIFY_CENTER: chunkX = _x + (_w - chunkW) / 2; break;
275: 	case JUSTIFY_RIGHT: chunkX = _x + _w - chunkW - _rightMargin; break;
276: 	}
277: 	if (curLine.equals("\n") || curLine.equals("\r")) chunkY += chunkH;
278: 	else g.fillRect(chunkX, chunkY - chunkH, chunkW, chunkH);
279:       }
280:     }
281: 
282:     g.setColor(_textColor);
283:     chunkX = _x + _leftMargin;
284:     chunkY = _y + _topMargin + _lineHeight + _lineSpacing;
285:     lines = new StringTokenizer(_curText, "\n\r", true);
286:     while (lines.hasMoreTokens()) {
287:       String curLine = lines.nextToken();
288:       //if (curLine.equals("\r")) continue;
289:       int chunkW = _fm.stringWidth(curLine);
290:       switch (_alignment) {
291:       case JUSTIFY_LEFT: break;
292:       case JUSTIFY_CENTER: chunkX = _x + ( _w - chunkW ) / 2; break;
293:       case JUSTIFY_RIGHT: chunkX = _x + _w  - chunkW; break;
294:       }
295:       if (curLine.equals("\n")  || curLine.equals("\r")) chunkY += chunkH;
296:       else g.drawString(curLine, chunkX, chunkY);
297:     }
298:   }
299: 
300: 
301: 
302:   ////////////////////////////////////////////////////////////////
303:   // event handlers
304: 
305:   /** When the user presses a key when a FigText is selected, that key
306:    *  should be added to the current string, or if the key was
307:    *  backspace, the last character is removed.  Needs-More-Work: Should
308:    *  also catch arrow keys and mouse clicks for full text
309:    *  editing... someday... */
310:   public void keyTyped(KeyEvent ke) {
311:     if (ke.getModifiers() != 0) return;
312:     char c = ke.getKeyChar();
313:     if (!Character.isISOControl(c)) {
314:       startTrans();
315:       append(c);
316:       endTrans();
317:       ke.consume();
318:     }
319:   }
320: 
321:   public void keyPressed(KeyEvent ke) {
322:     if (ke.getKeyCode() == KeyEvent.VK_BACK_SPACE) {
323:       startTrans();
324:       deleteLastChar();
325:       endTrans();
326:       ke.consume();
327:     }
328:     if (ke.getKeyCode() == KeyEvent.VK_ENTER) {
329:       startTrans();
330:       append('\n');
331:       endTrans();
332:       ke.consume();
333:     }
334:   }
335:   public void keyReleased(KeyEvent ke) { }
336: 
337:   
338:   ////////////////////////////////////////////////////////////////
339:   // internal utility functions
340: 
341:   /** Compute the overall width and height of the FigText object based
342:    *  on the font, font size, and current text. Needs-More-Work: Right
343:    *  now text objects can get larger when you type more, but they
344:    *  do not get smaller when you backspace.  */
345:   protected void calcBounds() {
346:     if (_font == null) return;
347:     if (_fm == null) _fm = Toolkit.getDefaultToolkit().getFontMetrics(_font);
348:     int overallW = 0;
349:     int numLines = 1;
350:     StringTokenizer lines = new StringTokenizer(_curText, "\n\r", true);
351:     while (lines.hasMoreTokens()) {
352:       String curLine = lines.nextToken();
353:       int chunkW = _fm.stringWidth(curLine);
354:       if (curLine.equals("\n") || curLine.equals("\r")) numLines++;
355:       else overallW = Math.max(chunkW, overallW);
356:     }
357:     _lineHeight = _fm.getHeight();
358:     int maxDescent = _fm.getMaxDescent();
359:     int overallH = (_lineHeight + _lineSpacing) * numLines +
360:       _topMargin + _botMargin + maxDescent;
361:     overallW = Math.max(MIN_TEXT_WIDTH, overallW + _leftMargin + _rightMargin);
362:     switch (_alignment) {
363:     case JUSTIFY_LEFT: break;
364:     case JUSTIFY_CENTER: if (_w < overallW) _x -= (overallW - _w) / 2; break;
365:     case JUSTIFY_RIGHT: if (_w < overallW) _x -= (overallW - _w); break;
366:     }
367:     _w = _expandOnly ? Math.max(_w, overallW) : overallW;
368:     _h = _expandOnly ? Math.max(_h, overallH) : overallH;
369:   }
370: 
371: } /* end class FigText */
