39: /**
40:  * Factory to create UML classes for the UML
41:  * Foundation::ExtensionMechanisms package.
42:  *
43:  * @since ARGO0.11.2
44:  * @author Thierry Lach
45:  * @stereotype singleton
46:  */
47: public class ExtensionMechanismsFactory extends AbstractUmlModelFactory {
48: 
49:     /** Singleton instance.
50:      */
51:     private static final ExtensionMechanismsFactory SINGLETON =
52: 	new ExtensionMechanismsFactory();
53: 
54:     /**
55:      * Singleton instance access method.
56:      *
57:      * @return the factory instance.
58:      */
59:     public static ExtensionMechanismsFactory getFactory() {
60:         return SINGLETON;
61:     }
62: 
63:     /** Don't allow instantiation
64:      */
65:     private ExtensionMechanismsFactory() {
66:     }
67: 
68:     /** Create an empty but initialized instance of a UML Stereotype.
69:      *
70:      *  @return an initialized UML Stereotype instance.
71:      */
72:     public Object/*MStereotype*/ createStereotype() {
73:         MStereotype modelElement =
74: 	    MFactory.getDefaultFactory().createStereotype();
75: 	super.initialize(modelElement);
76: 	return modelElement;
77:     }
78: 
79:     /** Create an empty but initialized instance of a UML TaggedValue.
80:      *
81:      *  @return an initialized UML TaggedValue instance.
82:      */
83:     public MTaggedValue createTaggedValue() {
84:         MTaggedValue modelElement =
85: 	    MFactory.getDefaultFactory().createTaggedValue();
86: 	super.initialize(modelElement);
87: 	return modelElement;
88:     }
89: 
90:     /**
91:      * Builds a stereotype for some kind of modelelement.
92:      */
93:     public MStereotype buildStereotype(Object mObj,
94:                                        Object textObj,
95:                                        Object nsObj) {
96:         MModelElement me = (MModelElement) mObj;
97:         String text = (String) textObj;
98:         MNamespace ns = (MNamespace) nsObj;
99:     	if (me == null || text == null || ns == null)
100: 	    throw new IllegalArgumentException("one of the arguments is null");
101:     	MStereotype stereo = (MStereotype) createStereotype();
102:     	stereo.setName(text);
103:     	stereo.setBaseClass(ExtensionMechanismsHelper.getHelper()
104: 			    .getMetaModelName(me));
105:     	MStereotype stereo2 =
106: 	    ExtensionMechanismsHelper.getHelper().getStereotype(ns, stereo);
107:     	if (stereo2 != null) {
108: 	    stereo2.addExtendedElement(me);
109: 	    UmlFactory.getFactory().delete(stereo);
110: 	    return stereo2;
111:     	} else {
112: 	    ns.addOwnedElement(stereo);
113: 	    stereo.addExtendedElement(me);
114: 	    return stereo;
115:     	}
116:     }
117: 
118:     /**
119:      * Builds an initialized stereotype.
120:      *
121:      * @param text is the name of the stereotype
122:      * @param ns namespace
123:      * @return an initialized stereotype.
124:      */
125:     public Object/*MStereotype*/ buildStereotype(String text, Object ns) {
126:     	MStereotype stereo = (MStereotype) createStereotype();
127:     	stereo.setName(text);
128:     	if (ns != null && ns instanceof MNamespace)
129:     	    stereo.setNamespace((MNamespace) ns);
130:     	return stereo;
131:     }
132: 
133:     public MStereotype buildStereotype(Object/*MModelElement*/ modelElement,
134: 				       String text) {
135:         MModelElement m = (MModelElement) modelElement;
136:         // if (m == null && text == null)
137: 	//  throw new IllegalArgumentException("one of the arguments is null");
138:         MStereotype stereo = (MStereotype) createStereotype();
139:         stereo.setName(text);
140:         stereo.setBaseClass(ExtensionMechanismsHelper.getHelper()
141: 			    .getMetaModelName(m));
142:         MStereotype stereo2 =
143: 	    ExtensionMechanismsHelper.getHelper().getStereotype(stereo);
144:         if (stereo2 != null) {
145:             stereo2.addExtendedElement(m);
146:             UmlFactory.getFactory().delete(stereo);
147:             return stereo2;
148:         } else {
149:             ((MModel) ProjectManager.getManager().getCurrentProject()
150: 		    .getModel())
151: 		.addOwnedElement(stereo);
152:             if (m != null)
153:                 stereo.addExtendedElement(m);
154:             return stereo;
155:         }
156:     }
157: 
158:     /**
159:      * Build an initialized instance of a UML TaggedValue.
160:      *
161:      * @param tag is the tag name (a String).
162:      * @param value is the value (a String).
163:      * @return an initialized UML TaggedValue instance.
164:      */
165:     public MTaggedValue buildTaggedValue(String tag, String value) {
166:         MTaggedValue tv = createTaggedValue();
167:         tv.setTag(tag);
168:         tv.setValue(value);
169:         return tv;
170:     }
171: 
172:     public void deleteStereotype(MStereotype elem) { }
173: 
174:     public void deleteTaggedValue(MTaggedValue elem) { }
175: 
176:     /**
177:      * Copies a stereotype.
178:      *
179:      * @param source is the stereotype to copy.
180:      * @param ns is the namespace to put the copy in.
181:      * @return a newly created stereotype
182:      */
183:     public MStereotype copyStereotype(MStereotype source, MNamespace ns) {
184: 	MStereotype st = (MStereotype) createStereotype();
185: 	ns.addOwnedElement(st);
186: 	doCopyStereotype(source, st);
187: 	return st;
188:     }
189: 
190:     /**
191:      * Used by the copy functions. Do not call this function directly.
192:      */
193:     private void doCopyStereotype(MStereotype source, MStereotype target) {
194: 	CoreFactory.getFactory().doCopyGeneralizableElement(source, target);
195: 	target.setBaseClass(source.getBaseClass());
196: 	target.setIcon(source.getIcon());
197: 	// TODO: constraints
198: 	// TODO: required tags
199:     }
200: }
