498:     /**
499:      * Overridden to set Argo-specific RenderingHints to determine whether
500:      * or not antialiasing should be turned on.
501:      */
502:     public synchronized void paint(Graphics g) {
503:         if (!shouldPaint())
504:             return;
505: 
506:         if (g instanceof Graphics2D) {
507:             Graphics2D g2 = (Graphics2D) g;
508:             g2.setRenderingHints(_argoRenderingHints);
509: 	    double scale = getScale();
510:             g2.scale(scale, scale);
511:         }
512:         getLayerManager().paint(g);
513:         //getLayerManager().getActiveLayer().paint(g);
514:         if (_canSelectElements) {
515:             _selectionManager.paint(g);
516:             _modeManager.paint(g);
517:         }        
518:     }
519:     
520:     /**
521:      * Construct a new set of RenderingHints to reflect current user
522:      * settings.
523:      */
524:     private void setupRenderingHints() {
525:         _argoRenderingHints = new RenderingHints(null);
526: 
527:         _argoRenderingHints.put(RenderingHints.KEY_FRACTIONALMETRICS, 
528:             RenderingHints.VALUE_FRACTIONALMETRICS_ON);
529:         
530:         if (Configuration.getBoolean(Argo.KEY_SMOOTH_EDGES, false)) {
531:             _argoRenderingHints.put(RenderingHints.KEY_RENDERING, 
532:                 RenderingHints.VALUE_RENDER_QUALITY);
533:             _argoRenderingHints.put(RenderingHints.KEY_ANTIALIASING, 
534:                 RenderingHints.VALUE_ANTIALIAS_ON);
535:             _argoRenderingHints.put(RenderingHints.KEY_TEXT_ANTIALIASING, 
536:                 RenderingHints.VALUE_TEXT_ANTIALIAS_ON);        
537:         }
538:         else {
539:             _argoRenderingHints.put(RenderingHints.KEY_RENDERING, 
540:                 RenderingHints.VALUE_RENDER_SPEED);
541:             _argoRenderingHints.put(RenderingHints.KEY_ANTIALIASING, 
542:                 RenderingHints.VALUE_ANTIALIAS_OFF);
543:             _argoRenderingHints.put(RenderingHints.KEY_TEXT_ANTIALIASING, 
544:                 RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);        
545:         }
546:     }
547: }
