145:   /** Examine the given Object and Designer and, if
146:    *  appropriate, produce one or more ToDoItem's and add them to the
147:    *  offending design material's and the Designer's ToDoList. By
148:    *  default this is basically a simple if-statement that relies on
149:    *  predicate() to determine if there is some appropriate feedback,
150:    *  and toDoItem() to produce the ToDoItem.
151:    *
152:    *  The predicate() and toDoItem() pair of methods is simple and
153:    *  convient for many critics. More sophisticated critics that
154:    *  produce more than one ToDoItem per critiquing, or that produce
155:    *  ToDoItem's that contain information that was already computed in
156:    *  the predicate, should override critique. If you override this
157:    *  method, you should call super.critique().
158:    *
159:    * @see Critic#predicate
160:    # @see Critic#toDoItem */
161:   public void critique(Object dm, Designer dsgr) {
162:     //System.out.println("applying critic: " + _headline);
163:     if (predicate(dm, dsgr)) {
164:       //       if (Boolean.getBoolean("debug")) {
165:       // 	System.out.println(this.toString() + " detected error");
166:       //       }
167:       ToDoItem item = toDoItem(dm, dsgr);
168:       if (dm instanceof DesignMaterial) ((DesignMaterial)dm).inform(item);
169:       dsgr.inform(item);
170:     }
171: //     else {
172: //       if (Boolean.getBoolean("debug")) {
173: // 	System.out.println(this.toString() + " found " + dm.toString()
174: // 			   + " OK ");
175: //       }
176: //     }
177:   }
