259:   /** Reply true iff this Critic can execute. This fact is normally
260:    *  determined by a ControlMech. */
261:   public boolean isActive() { return _isActive; }
262: 
263:   /** Make this critic active. From now on it can be applied to a
264:    *  design material in critiquing. */
265:   public void beActive() { _isActive = true; }
266: 
267:   /** Make this critic inactive. From now on it will be idle and will
268:    *  not be applied to a design material in critiquing. */
269:   public void beInactive() { _isActive = false; }
270: 
271:   /** Add some attribute used by ControlMech to determine if this
272:    *  Critic should be active. Critics store control record so that
273:    *  stateful ControlMech's do not need to store a parallel data
274:    *  structure. But Critic's do not directy use or modify this
275:    *  data. */
276:   public Object addControlRec(String name, Object controlData) {
277:     return _controlRecs.put(name, controlData);
278:   }
279: 
280:   /** Reply the named control record, or null if not defined. */
281:   public Object getControlRec(String name) {
282:     return _controlRecs.get(name);
283:   }
284: 
285:   /** This is a convient method for accessing one well-known control
286:    *  record. The enabled control record is a boolean that the user can
287:    *  turn on or off to manually enable or disable this Critic. It is
288:    *  normally combined with other ControlMech determinations with a
289:    *  logic-and. */
290:   public boolean isEnabled() {
291:     return  ((Boolean) getControlRec(ENABLED)).booleanValue();
292:   }
293: 
294:   /** Reply the HushOrder that is defined for this critic. */
295:   public HushOrder hushOrder() {
296:     return (HushOrder)getControlRec(SNOOZE_ORDER);
297:   }
298: 
299:   /** Disable this Critic for the next few minutes. */
300:   public void hush() { hushOrder().hush(); }
301: 
302:   /** Lift any previous HushOrder. */
303:   public void unhush() { hushOrder().unhush(); }
304: 
305:   /** Reply true iff this Critic is relevant to the decisions that
306:    *  the Designer is considering. By default just asks the Designer if
307:    *  he/she is considering my decisionCategory. Really this is
308:    *  something for a ControlMech to compute, but if a subclass of
309:    *  Critic encapsulates some information you may need to override
310:    *  this method. */
311:   public boolean isRelevantToDecisions(Designer dsgr) {
312:     Enumeration enum = getSupportedDecisions().elements();
313:     while (enum.hasMoreElements()) {
314:       Decision d = (Decision) enum.nextElement();
315:       //if (dsgr.isConsidering(d)) return true;
316:       if (d.getPriority() > 0) return true;
317:     }
318:     return false;
319:   }
320: 
321:   /** Reply true iff this Critic is relevant to the goals that the
322:    *  Designer is trying to achieve. By default, all Critic's are
323:    *  relevant regardless of the GoalModel. Really this is something for a
324:    *  ControlMech to compute, but if a subclass of Critic encapsulates
325:    *  some information you may need to override this method. <p>
326:    *
327:    *  Needs-More-Work: I would like a better default action, but goals
328:    *  are typed and their values must be interperted by critics. They
329:    *  are not as generic as the DecisionModel. */
330:   public boolean isRelevantToGoals(Designer dsgr) {
331:     return true;
332:   }
