375:     return _description;
376:   }
377:   public void setDescription(String d) {  _description = d; }
378: 
379:   /** Reply the moreInfoURL used in feedback produced by this Critic. */
380:   public String getMoreInfoURL(Set offenders, Designer dsgr) {
381:     return _moreInfoURL;
382:   }
383:   public void setMoreInfoURL(String m) {  _moreInfoURL = m; }
384: 
385:   ////////////////////////////////////////////////////////////////
386:   // design feedback
387: 
388:   /** Reply the ToDoItem that the designer should see iff predicate()
389:    *  returns true. By default it just fills in the fields of the
390:    *  ToDoItem from accessor methods of this Critic. Critic Subclasses
391:    *  may override this method or the accessor methods to add computed
392:    *  fields to the ToDoItem.
393:    *
394:    *  Needs-More-Work: Critic's may want to add new fields to a
395:    *  ToDoItem to make stillValid more efficent.
396:    *
397:    * @see Critic#critique */
398:   public ToDoItem toDoItem(Object dm, Designer dsgr) {
399:     return new ToDoItem(this, dm, dsgr);
400:   }
401: 
402:   ////////////////////////////////////////////////////////////////
403:   // issue resolution
404: 
405:   /** Needs-More-Work: Not implemented yet. The idea is that some
406:    *  problems identified by Critic's can be fixed with certain design
407:    *  manipulations (or transforms) that can be applied automatically
408:    *  to resolve the problem. This method replies true iff the given
409:    *  problem can be fixed. The fixIt() method actually does the fix.
410:    *
411:    * @see Critic@fixIt */
412:   public boolean canFixIt(ToDoItem item) {
413:     return false;
414:   }
415: 
416:   /** Needs-More-Work: Not implemented yet. If the given ToDoItem can
417:    *  be fixed automaically, and the user wants that to happen, then do
418:    *  it. Obviously, this depends on the specific Critic and
419:    *  problem. By default this method does nothing.
420:    *
421:    * @see Critic#canFixIt */
422:   public void fixIt(ToDoItem item, Object arg) { }
423: 
424:   /** Reply a string that describes this Critic. Mainly useful for
425:    *  debugging. */
426:   public String toString() {
427:     return this.getClass().getName() + "(" +
428:       getCriticType() + "," +
429:       getDecisionCategory() + "," +
430:       getHeadline() + ")";
431:   }
432: 
433:   ////////////////////////////////////////////////////////////////
434:   // image loading
435:   
436:     protected static ImageIcon loadIconResource(String name) {
437:     String imgName = imageName(name);
438:     ImageIcon res = null;
439:     try {
440:       java.net.URL imgURL = Critic.class.getResource(imgName);
441:       return new ImageIcon(imgURL);
442:     }
443:     catch (Exception ex) {
444:       return new ImageIcon(name);
445:     }
446:   }
447: 
448:   protected static String imageName(String name) {
449:     return "/uci/Images/" + stripJunk(name) + ".gif";
450:   }
451: 
452:   protected static String stripJunk(String s) {
453:     String res = "";
454:     int len = s.length();
455:     for (int i = 0; i < len; i++) {
456:       char c = s.charAt(i);
457:       if (Character.isJavaLetterOrDigit(c)) res += c;
458:     }
459:     return res;
460:   }
