355:     public String generateAttribute(Object handle, boolean documented) {
356: 	MAttribute attr = (MAttribute)handle;
357: 	String s = "";
358: 
359: 	String make_get = attr.getTaggedValue("get");
360: 	String make_set = attr.getTaggedValue("set");
361: 
362: 	boolean gen_accessor = false;
363: 
364: 	gen_accessor = (((make_get != null) && (make_get.equals("true"))) ||
365: 			((make_set != null) && (make_set.equals("true"))));
366: 
367: 	/*
368: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
369: 	 *
370: 	 * Was:
371: 	 *
372: 	 s += DocumentationManager.getDocs(attr) + "\n" + INDENT;
373: 	*/
374: 
375: 	if (documented)
376: 	    s += generateConstraintEnrichedDocComment (attr) + "\n" + INDENT;
377: 	if (gen_accessor)
378: 	    s += " private ";
379: 	else
380: 	    s += generateVisibility(attr);
381: 
382: 	s += generateScope(attr);
383: 	s += generateChangability(attr);
384: 	if (!MMultiplicity.M1_1.equals(attr.getMultiplicity())) {
385: 	    String temp = generateMultiplicity(attr.getMultiplicity());
386: 	    if (temp.length() > 0) {
387: 		s += temp + " ";
388: 	    }
389: 	}
390: 
391: 	MClassifier type = attr.getType();
392: 	if (type != null) {
393: 	    s += generateClassifierRef(type) + " ";
394: 	}
395: 
396: 	String slash = "";
397: 	//    if (attr.containsStereotype(MStereotype.DERIVED)) slash = "/";
398: 	String attr_name = attr.getName();
399: 	MVisibilityKind vis = attr.getVisibility();
400: 
401: 	if (MVisibilityKind.PUBLIC.equals(vis)) {
402: 	    // use original attribute name, no change
403: 	}
404: 	if (MVisibilityKind.PRIVATE.equals(vis)) {
405: 	    attr_name = attr.getOwner().getName() + "_" + attr_name;
406: 
407: 	}
408: 	if (MVisibilityKind.PROTECTED.equals(vis)) {
409: 	    // use orignial name for the moment
410: 	}
411: 
412: 	if (gen_accessor) attr_name = "m_" + attr_name;
413: 
414: 	s += slash + generateName(attr_name);
415: 	MExpression init = attr.getInitialValue();
416: 	if (init != null) {
417: 	    String initStr = generateExpression(init).trim();
418: 	    if (initStr.length() > 0)
419: 		s += " = " + initStr;
420: 	}
421: 
422: 	s += ";\n";
423: 	// s += generateConstraints(attr);  Removed 2001-09-26 STEFFEN ZSCHALER
424: 
425: 	// look if get and set methods are needed (Marian Heddesheimer)
426: 
427: 	//  if get and set are set, visibility is set to same as orig attribute
428: 	//  and a variable with m_ prefix is created.
429: 
430: 
431: 	if ( gen_accessor ) {
432: 
433: 	    s += "\n";
434: 
435: 	    s += INDENT + generateVisibility(attr) + " " + generateClassifierRef(type) + " " + attr.getName() + " {\n";
436: 
437: 	    if ( (make_set != null) && (make_set.equals("true")) )
438: 		s += INDENT + INDENT + "set { m_" + attr.getName() + " = value; } \n";
439: 
440: 	    if ( (make_get != null) && (make_get.equals("true")) )
441: 		s += INDENT + INDENT + "get { return m_" + attr.getName() + "; } \n";
442: 
443: 	    s += INDENT + "}\n";
444: 	}
445: 
446: 	return s;
447:     }
