496:     public String generateClassifier(Object handle) {
497: 	MClassifier cls = (MClassifier) handle;
498: 	String generatedName = generateName(cls.getName());
499: 	String classifierKeyword;
500: 	if (cls instanceof MClass) classifierKeyword = "class";
501: 	else if (cls instanceof MInterface) classifierKeyword = "interface";
502: 	else return ""; // actors and use cases
503: 
504: 	StringBuffer sb = new StringBuffer(80);
505: 	sb.append(DocumentationManager.getComments(cls));  // Add the comments for this classifier first.
506: 
507: 	/*
508: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
509: 	 *
510: 	 * Was:
511: 	 *
512: 	 sb.append(DocumentationManager.getDocs(cls)).append("\n");
513: 	*/
514: 	sb.append (generateConstraintEnrichedDocComment (cls)).append ("\n");
515: 
516: 	sb.append(generateVisibility(cls.getVisibility()));
517: 	if (cls.isAbstract() && !(cls instanceof MInterface)) {
518: 	    if (VERBOSE) sb.append("/* abstract */ ");
519: 	}
520: 	if (cls.isLeaf()) {
521: 	    if (VERBOSE) sb.append("/* final */ ");
522: 	}
523: 	sb.append(classifierKeyword).append(" ").append(generatedName);
524: 	String baseClass = generateGeneralzation(cls.getGeneralizations());
525: 	String tv = null;
526: 	if (!baseClass.equals("")) sb.append(' ').append(": ").append(baseClass);
527: 
528: 	// nsuml: realizations!
529: 	if (cls instanceof MClass) {
530: 	    String interfaces = generateSpecification((MClass) cls);
531: 	    if (!interfaces.equals("")) {
532: 		if (baseClass.equals(""))
533: 		    sb.append(": ");
534: 		else
535: 		    sb.append(", ");
536: 		sb.append(interfaces);
537: 	    }
538: 	}
539: 	sb.append("\n{");
540: 
541: 	tv = generateTaggedValues(cls);
542: 	if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv);
543: 
544: 	// sb.append(generateConstraints(cls)); Removed 2001-09-26 STEFFEN ZSCHALER
545: 
546: 
547: 	// generate constructor (Marian Heddesheimer)
548: 	String make_constructor = cls.getTaggedValue("constructor");
549: 	if ( (make_constructor != null) && (make_constructor.equals("true")) ) {
550: 	    sb.append(INDENT).append("function ").append(cls.getName()).append("() {\n");
551: 	    sb.append(generateSection(cls));
552: 	    sb.append(INDENT).append("}\n");
553: 	}
554: 
555: 
556: 	Collection strs = UmlHelper.getHelper().getCore().getAttributes(cls);
557: 	if (strs != null) {
558: 	    sb.append('\n');
559: 
560: 	    if (cls instanceof MClass) sb.append(INDENT).append("// Attributes\n");
561: 	    Iterator strEnum = strs.iterator();
562: 	    while (strEnum.hasNext()) {
563: 		MStructuralFeature sf = (MStructuralFeature) strEnum.next();
564: 		sb.append('\n').append(INDENT).append(generate(sf));
565: 		tv = generateTaggedValues(sf);
566: 		if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv).append('\n');
567: 	    }
568: 	}
569: 
570: 	Collection ends = cls.getAssociationEnds();
571: 	if (ends != null) {
572: 	    sb.append('\n');
573: 	    if (cls instanceof MClass) sb.append(INDENT).append("// Associations\n");
574: 	    Iterator endEnum = ends.iterator();
575: 	    while (endEnum.hasNext()) {
576: 		MAssociationEnd ae = (MAssociationEnd) endEnum.next();
577: 		MAssociation a = ae.getAssociation();
578: 		sb.append('\n').append(INDENT).append(generateAssociationFrom(a, ae));
579: 		tv = generateTaggedValues(a);
580: 		if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv);
581: 
582: 		// sb.append(generateConstraints(a));  Removed 2001-09-26 STEFFEN ZSCHALER Why was this not in generateAssociationFrom ?
583: 	    }
584: 	}
585: 
586: 	// TODO: constructors
587: 	Collection behs = UmlHelper.getHelper().getCore().getOperations(cls);
588: 	if (behs != null) {
589: 	    sb.append ('\n');
590: 	    sb.append (INDENT).append ("// Operations\n");
591: 
592: 	    Iterator behEnum = behs.iterator();
593: 
594: 	    while (behEnum.hasNext()) {
595: 		MBehavioralFeature bf = (MBehavioralFeature) behEnum.next();
596: 
597: 		sb.append ('\n').append (INDENT).append (generate (bf));
598: 
599: 		tv = generateTaggedValues((MModelElement) bf);
600: 
601: 		if ((cls instanceof MClass) &&
602: 		    (bf instanceof MOperation) &&
603: 		    (!((MOperation) bf).isAbstract())) {
604: 		    sb.append ('\n').append (INDENT).append ("{\n");
605: 
606: 		    if (tv.length() > 0) sb.append (INDENT).append (tv);
607: 
608: 		    sb.append (generateMethodBody ((MOperation) bf)).append ('\n')
609: 			.append (INDENT).append ("}\n");
610: 		}
611: 		else {
612: 		    sb.append (";\n");
613: 		    if (tv.length() > 0) sb.append (INDENT).append (tv).append ('\n');
614: 		}
615: 	    }
616: 	}
617: 	sb.append("} /* end ").append(classifierKeyword).append(' ').append(generatedName).append(" */\n");
618: 
619: 	return sb.toString();
