806:     public String generateConstraintEnrichedDocComment (MModelElement me) {
807: 	// Retrieve any existing doccomment
808: 	String sDocComment = DocumentationManager.getDocs (me, GeneratorCSharp.INDENT);
809: 
810: 	if (sDocComment != null) {
811: 	    // Fix Bug in documentation manager.defaultFor --> look for current INDENT
812: 	    // and use it
813: 	    for (int i = sDocComment.indexOf ('\n');
814: 		 i >= 0 && i < sDocComment.length();
815: 		 i = sDocComment.indexOf ('\n', i + 1)) {
816: 		sDocComment = sDocComment.substring (0, i + 1) +
817: 		    INDENT + sDocComment.substring (i + 1);
818: 	    }
819: 	}
820: 
821: 	// Extract constraints
822: 	Collection cConstraints = me.getConstraints();
823: 
824: 	if (cConstraints.size() == 0) {
825: 	    return (sDocComment != null) ? (sDocComment) : ("");
826: 	}
827: 
828: 	// Prepare doccomment
829: 	if (sDocComment != null) {
830: 	    // Just remove closing */
831: 	    sDocComment = sDocComment.substring (0, sDocComment.indexOf ("*/") + 1);
832: 	}
833: 	else {
834: 	    if (VERBOSE) {
835: 		sDocComment = INDENT + "/**\n" +
836: 		    INDENT + " * \n" +
837: 		    INDENT + " *";
