340:     /**
341:      * Determines the preferred size of the container argument using
342:      * this grid layout.  The preferred size of a grid layout is
343:      * dependant on the cellSizing scheme.<p>
344:      *
345:      * MAXPREFERRED and FITPARENT use the same formula to calculate
346:      * prefered size.<p>
347:      *
348:      * The prefered width using MAXPREFERRED or FITPARENT is the
349:      * largest preferred width of any of the widths in the container
350:      * times the number of columns, plus the horizontal padding times
351:      * the number of columns plus one, plus the left and right insets
352:      * of the target container.<p>
353:      *
354:      * The preferred height using MAXPREFERRED or FITPARENT is the
355:      * largest preferred height of any of the heights in the container
356:      * times the number of rows, plus the vertical padding times the
357:      * number of rows plus one, plus the top and bottom insets of the
358:      * target container.<p>
359:      *
360:      * The prefered width using ROWCOLPREFERRED is the largest
361:      * preferred is the sum of the widths of of all columns, plus the
362:      * horizontal padding times the number of columns plus one, plus
363:      * the left and right insets of the target container.<p>
364:      *
365:      * The prefered height using ROWCOLPREFERRED is the largest
366:      * preferred is the sum of the heights of of all columns, plus the
367:      * horizontal padding times the number of columns plus one, plus
368:      * the left and right insets of the target container.
369:      *
370:      * @param parent the container to be laid out 
371:      * @return the preferred dimensions to lay out the subcomponents
372:      * of the specified container
373:      */
374:     public Dimension preferredLayoutSize(Container parent) {
375:         synchronized (parent.getTreeLock()) {
376:             int componentCount = parent.getComponentCount();
377:             int actualRows = rows;
378:             int actualCols = cols;
379: 
380:             if (actualRows > 0) {
381:                 actualCols = (componentCount + actualRows - 1) / actualRows;
382:             } else {
383:                 actualRows = (componentCount + actualCols - 1) / actualCols;
384:             }
385: 
386:             colWidth = new int[actualCols];
387:             rowHeight = new int[actualRows];
388:             int largestPreferredWidth = 0;
389:             int largestPreferredHeight = 0;
390: 
391:             for (int c = 0; c < actualCols; ++c) {
392:                 for (int r = 0; r < actualRows; ++r) {
393:                     int i = r * actualCols + c;
394:                     if (i < componentCount) {
395:                         if (parent.getComponent(i).getPreferredSize().getWidth()
396: 			    > colWidth[c]) {
397:                             colWidth[c] =
398: 				(int) parent.getComponent(i)
399: 				    .getPreferredSize().getWidth();
400:                             if (colWidth[c] > largestPreferredWidth)
401: 				largestPreferredWidth = colWidth[c];
402:                         }
403:                         if (parent.getComponent(i)
404: 			    .getPreferredSize().getHeight()
405: 			    > rowHeight[r])
406: 			{
407:                             rowHeight[r] =
408: 				(int) parent.getComponent(i)
409: 				    .getPreferredSize().getHeight();
410:                             if (rowHeight[r] > largestPreferredHeight)
411: 				largestPreferredHeight = rowHeight[r];
412:                         }
413:                     }
414:                 }
415:             }
416: 
417:             return calculateSizes(parent, colWidth, rowHeight,
418: 				  actualRows, actualCols,
419: 				  largestPreferredWidth,
420: 				  largestPreferredHeight);
421:         }
422:     }
