592:     protected void positionComponentInCell(Component comp,
593: 					   int x, int y,
594: 					   int cellWidth, int cellHeight)
595:     {
596:         int componentWidth;
597:         int componentHeight;
598:         if (fill == VERTICAL || fill == NONE) {
599:             componentWidth = (int) comp.getPreferredSize().getWidth();
600:         }
601:         else {
602:             componentWidth = cellWidth;
603:         }
604: 
605:         if (fill == HORIZONTAL || fill == NONE) {
606:             componentHeight = (int) comp.getPreferredSize().getHeight();
607:         }
608:         else {
609:             componentHeight = cellHeight;
610:         }
611: 
612:         int xAnchor, yAnchor;
613:         if (fill == BOTH || fill == HORIZONTAL
614: 	    || anchor == NORTHWEST || anchor == WEST || anchor == SOUTHWEST)
615: 	{
616:             xAnchor = x;
617:         }
618:         else if (anchor == NORTHEAST || anchor == EAST || anchor == SOUTHEAST)
619: 	{
620:             xAnchor = x + cellWidth - componentWidth;
621:         }
622:         else {
623:             xAnchor = x + (cellWidth - componentWidth) / 2;
624:         }
625: 
626:         if (fill == BOTH || fill == VERTICAL
627: 	    || anchor == NORTH || anchor == NORTHWEST || anchor == NORTHEAST)
628: 	{
629:             yAnchor = y;
630:         }
631:         else if (anchor == SOUTHEAST || anchor == SOUTH || anchor == SOUTHWEST)
632: 	{
633:             yAnchor = y + cellHeight - componentHeight;
634:         }
635:         else {
636:             yAnchor = y + (cellHeight - componentHeight) / 2;
637:         }
638: 
639:         comp.setBounds(xAnchor, yAnchor, componentWidth, componentHeight);
640:     }
