28: package org.argouml.swingext;
29: 
30: import java.awt.*;
31: 
32: /**
33:  * Abstract class for a layout manager that sets all child components
34:  * in a single row or single column. PrefferedSize and MinimumSize are
35:  * calculated.
36:  *
37:  * @author Bob Tarling
38:  */
39: public abstract class LineLayout implements LayoutManager2 {
40: 
41:     public static final Orientation HORIZONTAL = Horizontal.getInstance();
42:     public static final Orientation VERTICAL = Vertical.getInstance();
43: 
44:     protected Orientation _orientation;
45:     protected int _gap = 0;
46:     
47:     public LineLayout(Orientation orientation) {
48:         _orientation = orientation;
49:     }
50: 
51:     public LineLayout(Orientation orientation, int gap) {
52:         _orientation = orientation;
53:         _gap = gap;
54:     }
55: 
56:     public void addLayoutComponent(String name, Component comp) {
57:     }
58: 
59:     public void addLayoutComponent(Component comp, Object constraints) {
60:     }
61: 
62:     public void removeLayoutComponent(Component comp) {
63:     }
64: 
65:     public Dimension preferredLayoutSize(Container parent) {
66:         int nComps = parent.getComponentCount();
67:         Dimension preferredSize = new Dimension(0, 0);
68:         int gap = 0;
69:         for (int i = 0; i < nComps; i++) {
70:             Component comp = parent.getComponent(i);
71:             if (comp.isVisible()) {
72:                 preferredSize =
73: 		    _orientation.addLength(preferredSize,
74: 					   _orientation
75: 					   .getLength(comp.getPreferredSize())
76: 					   + gap);
77:                 gap = _gap;
78:                 if (_orientation.getBreadth(comp.getPreferredSize())
79: 		    > _orientation.getBreadth(preferredSize))
80: 		{
81:                     preferredSize =
82: 			_orientation.setBreadth(preferredSize,
83: 						comp.getPreferredSize());
84:                 }
85:             }
86:         }
87:         preferredSize = DimensionUtility.add(preferredSize, parent.getInsets());
88:         return preferredSize;
89:     }
90: 
91:     public Dimension minimumLayoutSize(Container parent) {
92:         int nComps = parent.getComponentCount();
93:         Dimension minimumSize = new Dimension(0, 0);
94:         int gap = 0;
95:         for (int i = 0; i < nComps; i++) {
96:             Component comp = parent.getComponent(i);
97:             if (comp.isVisible()) {
98:                 minimumSize =
99: 		    _orientation.addLength(minimumSize,
100: 					   _orientation
101: 					   .getLength(comp.getMinimumSize())
102: 					   + gap);
103:                 gap = _gap;
104:                 if (_orientation.getBreadth(comp.getMinimumSize())
105: 		    > _orientation.getBreadth(minimumSize))
106: 		{
107:                     minimumSize =
108: 			_orientation.setBreadth(minimumSize,
109: 						comp.getMinimumSize());
110:                 }
111:             }
112:         }
113:         minimumSize = DimensionUtility.add(minimumSize, parent.getInsets());
114:         return minimumSize;
115:     }
116: 
117:     public Dimension maximumLayoutSize(Container parent) {
118:         int nComps = parent.getComponentCount();
119:         Dimension maximumSize =
120: 	    new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE);
121:         int gap = 0;
122:         for (int i = 0; i < nComps; i++) {
123:             Component comp = parent.getComponent(i);
124:             Dimension componentMaxSize = comp.getMaximumSize();
125:             if (comp.isVisible() && componentMaxSize != null) {
126:                 maximumSize =
127: 		    _orientation.addLength(maximumSize,
128: 					   _orientation
129: 					   .getLength(componentMaxSize)
130: 					   + gap);
131:                 gap = _gap;
132:                 if (_orientation.getBreadth(componentMaxSize)
133: 		    < _orientation.getBreadth(maximumSize))
134: 		{
135:                     maximumSize =
136: 			_orientation.setBreadth(maximumSize, componentMaxSize);
137:                 }
138:             }
139:         }
140:         maximumSize = DimensionUtility.add(maximumSize, parent.getInsets());
141:         return maximumSize;
142:     }
143: 
144:     public void invalidateLayout(Container target) { }
145:     public float getLayoutAlignmentX(Container target) { return (float) 0.5; }
146:     public float getLayoutAlignmentY(Container target) { return (float) 0.5; }
147: }
